class Solution {
public:
    std::vector<std::vector<std::string>> suggestedProducts(std::vector<std::string>& products, std::string searchWord) {
        std::sort(products.begin(), products.end());
        std::vector<std::vector<std::string>> res;
        std::string prefix = "";
        for (char ch : searchWord) {
            prefix += ch;
            auto it = std::lower_bound(products.begin(), products.end(), prefix);
            std::vector<std::string> suggestions;
            for (int i = 0; i < 3 && (it + i) != products.end(); ++i) {
                const std::string& prod = *(it + i);
                if (prod.rfind(prefix, 0) == 0) {
                    suggestions.push_back(prod);
                } else {
                    break;
                }
            }
            res.push_back(suggestions);
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<String>> suggestedProducts(String[] products, String searchWord) {
        java.util.Arrays.sort(products);
        java.util.List<java.util.List<String>> res = new java.util.ArrayList<>();
        StringBuilder prefix = new StringBuilder();
        for (char ch : searchWord.toCharArray()) {
            prefix.append(ch);
            String prefStr = prefix.toString();
            int idx = java.util.Arrays.binarySearch(products, prefStr);
            if (idx < 0) idx = -(idx + 1);
            java.util.List<String> suggestions = new java.util.ArrayList<>();
            for (int i = idx; i < Math.min(idx + 3, products.length); i++) {
                if (products[i].startsWith(prefStr)) {
                    suggestions.add(products[i]);
                } else {
                    break;
                }
            }
            res.add(suggestions);
        }
        return res;
    }
}

var suggestedProducts = function(products, searchWord) {
    products.sort();
    const res = [];
    let prefix = '';

    const bisectLeft = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    for (const ch of searchWord) {
        prefix += ch;
        const idx = bisectLeft(products, prefix);
        const suggestions = [];
        for (let i = idx; i < Math.min(idx + 3, products.length); i++) {
            if (products[i].startsWith(prefix)) {
                suggestions.push(products[i]);
            } else {
                break;
            }
        }
        res.push(suggestions);
    }
    return res;
};
